property.value:
let $takes := ('poll', 'pop', 'removeFirst', 'removeLast', 'pollFirst', 'pollLast', 'remove'),
    $appends := ('add', 'push', 'offer', 'addLast', 'addFirst', 'offerLast', 'offerFirst'),
    $names := function($e) {
      $e/descendant-or-self::*[self::VariableAccess or self::FieldAccess]/@Name
    },
    $stateOf := function($e, $key) {
      $e/self::MethodCall[@MethodName = 'get'][ArgumentList/*[1][self::VariableAccess[@Name = $key]]]
        /*[1][self::VariableAccess or self::FieldAccess]/@Name
    },
    $removes := function($scope, $sources) {
      let $copies := $scope//LocalVariableDeclaration/VariableDeclarator[$names(*[2]) = $sources]/VariableId/@Name,
          $facts := ($copies, $sources)
      return exists($scope//MethodCall[*[1][self::VariableAccess][@Name = $copies]]
                      [@MethodName = ('removeIf', 'retainAll', 'clear')
                       or (@MethodName = ('remove', 'removeAll') and $names(ArgumentList/*[1]) = $facts)])
    }
return
//WhileStatement
  /(let $loop := .,
        $class := ancestor::ClassBody[1],
        $work := (.//MethodCall[@MethodName = $takes][ArgumentList/@Size = 0]
                    /*[1][self::VariableAccess or self::FieldAccess]/@Name)[1]
    return .//IfStatement
      /(let $key := *[position() > 1]//MethodCall[@MethodName = $appends]
                      [*[1][self::VariableAccess or self::FieldAccess][@Name = $work]]
                      /ArgumentList/*[1][self::VariableAccess]/@Name
        return *[1]/descendant-or-self::MethodCall
          [matches(@MethodName, '^(join|merge|union|meet|widen|addAll)', 'i')]
          [let $state := (for $part in (*[1], ArgumentList/*), $k in $key return $stateOf($part, $k))[1]
           return exists($state)
             and ($removes($loop/*[last()], $state)
                  or (some $call in $loop//MethodCall
                                      [*[1][self::ArgumentList or self::ThisExpression or self::TypeExpression]]
                      satisfies
                        (some $method in $class/MethodDeclaration[@Name = $call/@MethodName]
                                           [count(FormalParameters/FormalParameter) = $call/ArgumentList/@Size]
                         satisfies $removes($method/Block,
                           ($state, for $i in 1 to count($method/FormalParameters/FormalParameter)
                                    return if ($names($call/ArgumentList/*[$i]) = $state)
                                           then $method/FormalParameters/FormalParameter[$i]/VariableId/@Name
                                           else ())))))]))
